<?php
declare(strict_types=1);
if (session_status() === PHP_SESSION_NONE) session_start();
date_default_timezone_set('Africa/Lusaka');

require_once __DIR__ . '/store_header.php';

$branchId = (int)($_GET['bid'] ?? $_SESSION['current_branch_id'] ?? $_SESSION['branch_id'] ?? 0);
if ($branchId <= 0) $branchId = (int)($_SESSION['branch_id'] ?? 0);
$_SESSION['current_branch_id'] = $branchId;

if (empty($_SESSION['online_cart_csrf'])) {
    $_SESSION['online_cart_csrf'] = bin2hex(random_bytes(32));
}
$csrf = $_SESSION['online_cart_csrf'];

$cart = ($branchId > 0 && isset($_SESSION['carts'][$branchId]) && is_array($_SESSION['carts'][$branchId]))
    ? $_SESSION['carts'][$branchId] : [];

$count = 0; $subtotal = 0.0;
foreach ($cart as $item) {
    $q = max(0, (int)($item['qty'] ?? 0));
    $count += $q;
    $subtotal += (float)($item['price'] ?? 0) * $q;
}
$subtotal = round($subtotal, 2);

$prefillName = (string)($user_data['full_name'] ?? ($_SESSION['client_name'] ?? ''));
$prefillPhone = (string)($user_data['phone'] ?? '');
$prefillAddress = '';
$clientId = (int)($_SESSION['client_id'] ?? 0);
$pharmacyId = (int)($parent_pharmacy_id ?? 0);

if ($clientId > 0 && $branchId > 0 && $pharmacyId > 0) {
    $s = $conn->prepare('SELECT name, phone, address FROM customers WHERE client_id=? AND pharmacy_id=? AND branch_id=? LIMIT 1');
    if ($s) {
        $s->bind_param('iii', $clientId, $pharmacyId, $branchId);
        $s->execute();
        $r = $s->get_result()->fetch_assoc() ?: [];
        $s->close();
        if ($prefillName === '' && !empty($r['name'])) $prefillName = (string)$r['name'];
        if ($prefillPhone === '' && !empty($r['phone'])) $prefillPhone = (string)$r['phone'];
        $prefillAddress = (string)($r['address'] ?? '');
    }
}
?>
<!doctype html>
