<style>
:root{--c:#00a878;--c2:#007f61;--bg:#f5f7fa;--card:#fff;--text:#17212b;--muted:#6b7785;--border:#e4e9ef;--danger:#dc3545;--shadow:0 8px 30px rgba(23,33,43,.07)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}.cart-shell{max-width:1180px;margin:0 auto;padding:28px 18px 70px}.cart-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:22px}.eyebrow{font-size:12px;font-weight:800;letter-spacing:.12em;color:var(--c);text-transform:uppercase}.cart-heading h1{margin:4px 0 5px;font-size:32px}.cart-heading p{margin:0;color:var(--muted)}.continue{border:1px solid var(--border);background:#fff;color:var(--text);padding:11px 16px;border-radius:10px;text-decoration:none;font-weight:700}.layout{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:20px;align-items:start}.card{background:var(--card);border:1px solid var(--border);border-radius:16px;box-shadow:var(--shadow)}.card-head{padding:17px 18px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center}.clear{border:0;background:transparent;color:var(--danger);font-weight:700;cursor:pointer}.clear:disabled{opacity:.4;cursor:not-allowed}.item{display:grid;grid-template-columns:70px minmax(0,1fr) auto auto auto;gap:15px;align-items:center;padding:17px 18px;border-bottom:1px solid #edf0f3}.item:last-child{border-bottom:0}.thumb{width:70px;height:70px;border-radius:12px;background:#f1f6f5;display:grid;place-items:center;overflow:hidden}.thumb img{width:100%;height:100%;object-fit:cover}.thumb span{font-size:26px}.product h3{margin:0 0 5px;font-size:15px}.product small{display:block;color:var(--muted);margin-bottom:7px}.price{font-weight:800}.qty{display:flex;align-items:center;border:1px solid var(--border);border-radius:10px;overflow:hidden}.qty button{width:34px;height:36px;border:0;background:#f7f9fb;font-size:20px;cursor:pointer}.qty input{width:42px;height:36px;border:0;text-align:center;font-weight:700;outline:0}.line{font-weight:900;white-space:nowrap}.remove{border:0;background:transparent;color:var(--danger);font-weight:700;cursor:pointer}.summary{padding:20px;position:sticky;top:18px}.summary h2{margin:0 0 18px;font-size:20px}.row{display:flex;justify-content:space-between;gap:12px;margin:12px 0;color:#4e5a66}.row strong{color:var(--text)}.total{border-top:1px solid var(--border);padding-top:15px;margin-top:16px;font-size:19px}.checkout{width:100%;border:0;background:var(--c);color:#fff;border-radius:11px;padding:14px;font-size:15px;font-weight:800;cursor:pointer;margin-top:18px}.checkout:hover{background:var(--c2)}.checkout:disabled{opacity:.5;cursor:not-allowed}.note{margin-top:13px;font-size:12px;line-height:1.5;color:var(--muted)}.empty{text-align:center;padding:60px 20px}.empty .icon{font-size:48px;margin-bottom:12px}.empty h2{margin:0 0 7px}.empty p{color:var(--muted)}.shop{display:inline-block;background:var(--c);color:#fff;text-decoration:none;padding:12px 18px;border-radius:10px;font-weight:800}.toast{position:fixed;right:18px;bottom:18px;z-index:9999;background:#17212b;color:#fff;padding:13px 16px;border-radius:10px;box-shadow:var(--shadow);opacity:0;transform:translateY(10px);pointer-events:none;transition:.2s}.toast.show{opacity:1;transform:none}.modal{position:fixed;inset:0;z-index:9998;display:none;align-items:center;justify-content:center;padding:18px}.modal.open{display:flex}.backdrop{position:absolute;inset:0;background:rgba(15,23,42,.55)}.dialog{position:relative;width:min(520px,100%);max-height:92vh;overflow:auto;background:#fff;border-radius:18px;padding:24px;box-shadow:0 20px 70px rgba(0,0,0,.2)}.close{position:absolute;right:15px;top:10px;border:0;background:#f1f3f5;width:36px;height:36px;border-radius:50%;font-size:22px;cursor:pointer}.dialog h2{margin:5px 45px 5px 0}.intro{color:var(--muted);font-size:14px;margin-bottom:20px}.field{display:block;margin:14px 0}.field span{display:block;font-size:13px;font-weight:800;margin-bottom:7px}.field input,.field textarea,.field select{width:100%;border:1px solid #d8dee6;border-radius:10px;padding:12px 13px;font:inherit;outline:none;background:#fff}.field input:focus,.field textarea:focus,.field select:focus{border-color:var(--c);box-shadow:0 0 0 3px rgba(0,168,120,.1)}.message{margin-top:13px;padding:11px 12px;border-radius:9px;display:none;font-size:14px}.message.show{display:block}.message.error{background:#fff0f1;color:#a51d2a}.message.ok{background:#edf9f5;color:#087a5c}.success{display:none;text-align:center;padding:15px 4px}.success.show{display:block}.success-icon{width:64px;height:64px;border-radius:50%;background:#e9f8f3;color:var(--c);display:grid;place-items:center;font-size:30px;margin:5px auto 14px}.order-no{font-size:19px;font-weight:900;margin:10px 0}.success p{color:var(--muted);line-height:1.5}.actions{display:flex;gap:10px;justify-content:center;margin-top:18px}.actions a,.actions button{border:0;padding:11px 15px;border-radius:10px;font-weight:800;text-decoration:none;cursor:pointer}.primary{background:var(--c);color:#fff}.secondary{background:#eef2f5;color:var(--text)}@media(max-width:800px){.cart-shell{padding:18px 12px 45px}.cart-heading{align-items:flex-start;flex-direction:column}.cart-heading h1{font-size:27px}.layout{grid-template-columns:1fr}.summary{position:static}.item{grid-template-columns:58px 1fr auto;gap:11px}.thumb{width:58px;height:58px}.qty{grid-column:2}.line{grid-column:3;grid-row:1}.remove{grid-column:3;grid-row:2}.product{min-width:0}.continue{width:100%;text-align:center}.summary{padding:17px}}@media(max-width:430px){.item{padding:14px 12px}.product h3{font-size:14px}.line{font-size:14px}.dialog{padding:20px 16px}.cart-heading h1{font-size:24px}}
</style>
