<body>
<main class="cart-shell" id="cartShell" data-branch="<?= (int)$branchId ?>">
  <header class="cart-heading"><div><span class="eyebrow">YOUR SHOPPING CART</span><h1>Your Cart</h1><p id="subtitle"><?= $count ?> item<?= $count===1?'':'s' ?> ready for checkout</p></div><a class="continue" href="online_store.php?bid=<?= urlencode((string)$branchId) ?>">Continue shopping</a></header>
  <section class="layout">
    <div class="card"><div class="card-head"><strong>Cart items</strong><button class="clear" id="clearBtn" type="button" <?= !$cart?'disabled':'' ?>>Clear cart</button></div><div id="items">
    <?php if(!$cart): ?><div class="empty"><div class="icon">🛒</div><h2>Your cart is empty</h2><p>Add products from the online pharmacy store.</p><a class="shop" href="online_store.php?bid=<?= urlencode((string)$branchId) ?>">Shop now</a></div>
    <?php else: foreach($cart as $item): $id=(int)$item['id'];$q=max(1,(int)$item['qty']);$p=(float)$item['price'];$img=(string)($item['image']??''); ?><article class="item" data-id="<?= $id ?>"><div class="thumb"><?php if($img): ?><img src="<?= htmlspecialchars($img,ENT_QUOTES) ?>" alt="" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><?php endif; ?><span style="display:<?= $img?'none':'grid' ?>">💊</span></div><div class="product"><h3><?= htmlspecialchars((string)$item['name']) ?></h3><?php if(!empty($item['strength'])):?><small><?= htmlspecialchars((string)$item['strength']) ?></small><?php endif;?><div class="price">K <?= number_format($p,2) ?></div></div><div class="qty"><button type="button" data-q="minus">−</button><input type="number" min="1" value="<?= $q ?>"><button type="button" data-q="plus">+</button></div><strong class="line">K <?= number_format($p*$q,2) ?></strong><button class="remove" type="button">Remove</button></article><?php endforeach; endif; ?></div></div>
    <aside class="card summary"><h2>Order summary</h2><div class="row"><span>Items</span><strong id="count"><?= $count ?></strong></div><div class="row"><span>Subtotal</span><strong id="subtotal">K <?= number_format($subtotal,2) ?></strong></div><div class="row"><span>Delivery</span><span>Confirmed by pharmacy</span></div><div class="row total"><strong>Total</strong><strong id="total">K <?= number_format($subtotal,2) ?></strong></div><button class="checkout" id="checkoutBtn" type="button" <?= !$cart?'disabled':'' ?>>Proceed to checkout</button><div class="note">Stock, branch and online price are checked again on the server before your order is created.</div></aside>
  </section>
</main>
<div class="toast" id="toast"></div>
<div class="modal" id="modal"><div class="backdrop" data-close></div><section class="dialog" role="dialog" aria-modal="true"><button class="close" type="button" data-close>×</button><div id="checkoutView"><span class="eyebrow">COMPLETE ORDER</span><h2>Delivery details</h2><p class="intro">Enter where you want the pharmacy to deliver your order.</p><form id="checkoutForm"><label class="field"><span>Full name</span><input name="customer_name" required maxlength="120" value="<?= htmlspecialchars($prefillName,ENT_QUOTES) ?>"></label><label class="field"><span>Phone number</span><input name="phone" required maxlength="40" autocomplete="tel" value="<?= htmlspecialchars($prefillPhone,ENT_QUOTES) ?>"></label><label class="field"><span>Delivery address</span><textarea name="address" required maxlength="500" rows="4"><?= htmlspecialchars($prefillAddress,ENT_QUOTES) ?></textarea></label><label class="field"><span>Payment method</span><select name="payment_method" required><option value="Cash on Delivery">Cash on Delivery</option><option value="Mobile Money">Mobile Money</option><option value="Bank">Bank / Transfer</option></select></label><button class="checkout" id="placeBtn" type="submit">Place order</button><div class="message" id="msg"></div></form></div><div class="success" id="successView"><div class="success-icon">✓</div><h2>Order placed successfully</h2><div class="order-no" id="orderNo"></div><p>Your order has been sent to the pharmacy. You can follow it from your orders page.</p><div class="actions"><a class="primary" id="ordersLink" href="client_orders.php">View my orders</a><a class="secondary" href="online_store.php?bid=<?= urlencode((string)$branchId) ?>">Continue shopping</a></div></div></section></div>
<script>
window.BIGE_CART={branchId:<?= json_encode($branchId) ?>,csrf:<?= json_encode($csrf) ?>,api:'cart_api.php'};
(function(){const C=window.BIGE_CART,$=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),items=$('#items'),toast=$('#toast'),modal=$('#modal'),form=$('#checkoutForm'),msg=$('#msg');let timer;
function money(n){return 'K '+Number(n||0).toLocaleString('en-ZM',{minimumFractionDigits:2,maximumFractionDigits:2})}function notify(t,err=false){toast.textContent=t;toast.style.background=err?'#a51d2a':'#17212b';toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2800)}
async function api(data){data.bid=C.branchId;data.csrf=C.csrf;const r=await fetch(C.api,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(data)});let j;try{j=await r.json()}catch(e){throw new Error('The server returned an invalid response.')}if(!j.success)throw Object.assign(new Error(j.message||'Request failed'),j);return j}
function render(j){const arr=j.items||[];$('#count').textContent=j.cart_count||0;$('#subtotal').textContent=money(j.subtotal);$('#total').textContent=money(j.total);$('#subtitle').textContent=(j.cart_count||0)+' item'+((j.cart_count||0)===1?'':'s')+' ready for checkout';$('#clearBtn').disabled=!arr.length;$('#checkoutBtn').disabled=!arr.length;if(!arr.length){items.innerHTML='<div class="empty"><div class="icon">🛒</div><h2>Your cart is empty</h2><p>Add products from the online pharmacy store.</p><a class="shop" href="online_store.php?bid='+encodeURIComponent(C.branchId)+'">Shop now</a></div>';return}items.innerHTML=arr.map(x=>{const p=Number(x.price||0),q=Number(x.qty||1),img=x.image||'';return '<article class="item" data-id="'+Number(x.id)+'"><div class="thumb">'+(img?'<img src="'+esc(img)+'" alt="" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'grid\'">':'')+'<span style="display:'+(img?'none':'grid')+'">💊</span></div><div class="product"><h3>'+esc(x.name||'Product')+'</h3>'+(x.strength?'<small>'+esc(x.strength)+'</small>':'')+'<div class="price">'+money(p)+'</div></div><div class="qty"><button type="button" data-q="minus">−</button><input type="number" min="1" value="'+q+'"><button type="button" data-q="plus">+</button></div><strong class="line">'+money(p*q)+'</strong><button class="remove" type="button">Remove</button></article>'}).join('')}
function esc(v){return String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
items.addEventListener('click',async e=>{const row=e.target.closest('.item');if(!row)return;const id=row.dataset.id;try{if(e.target.closest('.remove')){const j=await api({action:'remove',item_id:id});render(j);notify('Item removed');return}const b=e.target.closest('[data-q]');if(b){const input=row.querySelector('input');let q=Math.max(1,parseInt(input.value||1,10));q+=b.dataset.q==='plus'?1:-1;const j=await api({action:'update',item_id:id,qty:q});render(j);notify('Cart updated')}}catch(err){notify(err.message,true)}});
items.addEventListener('change',async e=>{if(!e.target.matches('input'))return;const row=e.target.closest('.item');try{const q=Math.max(1,parseInt(e.target.value||1,10));const j=await api({action:'update',item_id:row.dataset.id,qty:q});render(j)}catch(err){notify(err.message,true)}});
$('#clearBtn').onclick=async()=>{if(!confirmCustom('Clear all items from your cart?'))return;try{render(await api({action:'clear'}));notify('Cart cleared')}catch(e){notify(e.message,true)}};
function confirmCustom(text){return new Promise(resolve=>{const d=document.createElement('div');d.className='modal open';d.innerHTML='<div class="backdrop"></div><section class="dialog" style="max-width:420px"><h2>Clear cart?</h2><p class="intro">'+esc(text)+'</p><div class="actions"><button class="secondary" id="no">Cancel</button><button class="primary" id="yes">Clear cart</button></div></section>';document.body.appendChild(d);d.querySelector('#no').onclick=()=>{d.remove();resolve(false)};d.querySelector('#yes').onclick=()=>{d.remove();resolve(true)}})}
$('#checkoutBtn').onclick=()=>{if(!$('#checkoutBtn').disabled){modal.classList.add('open');document.body.style.overflow='hidden'}};$$('[data-close]').forEach(x=>x.onclick=()=>{modal.classList.remove('open');document.body.style.overflow=''});
form.addEventListener('submit',async e=>{e.preventDefault();msg.className='message';msg.textContent='';$('#placeBtn').disabled=true;$('#placeBtn').textContent='Placing order...';try{const data=Object.fromEntries(new FormData(form).entries());data.action='checkout';const j=await api(data);$('#checkoutView').style.display='none';$('#successView').classList.add('show');$('#orderNo').textContent=j.order_number||'';$('#ordersLink').href='client_orders.php';items.innerHTML='<div class="empty"><div class="icon">✓</div><h2>Order placed</h2><p>Your cart is now empty.</p><a class="shop" href="online_store.php?bid='+encodeURIComponent(C.branchId)+'">Continue shopping</a></div>';$('#checkoutBtn').disabled=true;$('#clearBtn').disabled=true}catch(err){if(err.login_required){window.location.href='login_client.php?redirect='+encodeURIComponent('cart.php?bid='+C.branchId);return}msg.textContent=err.message;msg.className='message show error'}finally{$('#placeBtn').disabled=false;$('#placeBtn').textContent='Place order'}});
})();
</script>
</body></html>
